//Program to print the no.of even number within a range
public class EvenNumberBetweenaRangeUsingForLoop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
     for(int i=23;i<=60;i++) {
    	 if(i %2==0) {
    		 System.out.println(i);
    	 }
     }
	}

}
